--[[     分身环绕系统（Roblox Studio 正规脚本）     效果：激活开关后，手持物品会生成一圈无碰撞分身围绕你旋转     菜单：形状(圆形/螺旋/星形/球形) + 旋转速度 + 分身大小     放置：StarterPlayer > StarterPlayerScripts ]]  local Players = game:GetService("Players") local RunService = game:GetService("RunService")  local player = Players.LocalPlayer  -- ===== 配置 ===== local CONFIG = {     count  = 12,      -- 分身数量     speed  = 2.0,     -- 旋转速度     scale  = 1.0,     -- 大小倍率     shape  = "圆形",     radius = 5,     height = 0.5,     active = false, } local SHAPES = {"圆形", "螺旋", "星形", "球形"}  -- ===== 分身 ===== local folder = Instance.new("Folder"); folder.Name = "FxClones"; folder.Parent = workspace local clones = {} local lastTool = nil  local function clearClones()     for _, c in ipairs(clones) do if c then c:Destroy() end end     clones = {} end  local function offsetFor(i, total)     local a = (i - 1) / total * math.pi * 2     local r = CONFIG.radius * CONFIG.scale     if CONFIG.shape == "圆形" then         return Vector3.new(math.cos(a) * r, CONFIG.height, math.sin(a) * r)     elseif CONFIG.shape == "螺旋" then         return Vector3.new(math.cos(a) * r, CONFIG.height + (i - 1) * 0.5, math.sin(a) * r)     elseif CONFIG.shape == "星形" then         local rr = r * (0.5 + 0.5 * math.abs(math.cos(a * 2)))         return Vector3.new(math.cos(a) * rr, CONFIG.height, math.sin(a) * rr)     else -- 球形         local y = math.cos(a * 2) * r * 0.8         local rr = r * math.sin(a * 2)         return Vector3.new(math.cos(a) * rr, CONFIG.height + y, math.sin(a) * rr)     end end  local function getVisual(tool)     local h = tool:FindFirstChild("Handle")     if h then return h end     for _, v in ipairs(tool:GetDescendants()) do         if v:IsA("BasePart") then return v end     end     return nil end  local function spawnClones(tool)     clearClones()     local visual = getVisual(tool)     if not visual then return end     for i = 1, CONFIG.count do         local c = visual:Clone()         c.Name = "FxClone"         c.Anchored = true          -- 由脚本控制位置         c.CanCollide = false       -- ★ 无碰撞，碰撞箱只留在手上         c.Size = visual.Size * CONFIG.scale         for _, d in ipairs(c:GetDescendants()) do             if d:IsA("Sound") or d:IsA("ParticleEmitter") or d:IsA("Trail") then                 d:Enabled = false             end         end         c.Parent = folder         clones[i] = c     end end  local function update(dt)     if not CONFIG.active then return end     local char = player.Character     local root = char and char:FindFirstChild("HumanoidRootPart")     if not root or #clones == 0 then return end     local yaw = os.clock() * CONFIG.speed     for i, c in ipairs(clones) do         local b = offsetFor(i, #clones)         local cx, sz = math.cos(yaw), math.sin(yaw)         local ox = b.X * cx - b.Z * sz         local oz = b.X * sz + b.Z * cx         c.CFrame = CFrame.new(root.Position + Vector3.new(ox, b.Y, oz)) * CFrame.Angles(yaw, 0, 0)     end end RunService.Heartbeat:Connect(update)  -- 手持物品检测（每0.25秒） task.spawn(function()     while true do         task.wait(0.25)         local char = player.Character         local h = char and char:FindFirstChildOfClass("Humanoid")         local tool = h and h:FindFirstChildOfClass("Tool")         if tool ~= lastTool then             lastTool = tool             if CONFIG.active then                 if tool then spawnClones(tool) else clearClones() end             end         end     end end)  player.CharacterAdded:Connect(function()     task.wait(0.2)     lastTool = nil end)  -- ===== GUI ===== local gui = Instance.new("ScreenGui") gui.Name = "CloneMenu"; gui.ResetOnSpawn = false gui.Parent = player:WaitForChild("PlayerGui")  -- 开关按钮（右下角） local toggle = Instance.new("TextButton") toggle.Size = UDim2.fromOffset(84, 40) toggle.Position = UDim2.new(1, -104, 1, -60) toggle.BackgroundColor3 = Color3.fromRGB(45, 160, 90) toggle.TextColor3 = Color3.new(1, 1, 1) toggle.Font = Enum.Font.GothamBold toggle.TextSize = 14 toggle.Text = "分身：关" toggle.Parent = gui  -- 菜单面板 local panel = Instance.new("Frame") panel.Size = UDim2.fromOffset(230, 210) panel.Position = UDim2.new(1, -260, 1, -110) panel.BackgroundColor3 = Color3.fromRGB(25, 25, 35) panel.BackgroundTransparency = 0.08 panel.BorderSizePixel = 1 panel.BorderColor3 = Color3.fromRGB(90, 90, 120) panel.Visible = false panel.Parent = gui  local title = Instance.new("TextLabel") title.Size = UDim2.new(1, 0, 0, 26) title.BackgroundTransparency = 1 title.Text = "分身菜单" title.TextColor3 = Color3.new(1, 1, 1) title.Font = Enum.Font.GothamBold title.TextSize = 16 title.Parent = panel  -- 形状选择 local shapeLab = Instance.new("TextLabel") shapeLab.Size = UDim2.fromOffset(50, 22) shapeLab.Position = UDim2.fromOffset(6, 30) shapeLab.BackgroundTransparency = 1 shapeLab.Text = "形状:" shapeLab.TextColor3 = Color3.new(1, 1, 1) shapeLab.TextSize = 13 shapeLab.Parent = panel  for i, s in ipairs(SHAPES) do     local btn = Instance.new("TextButton")     btn.Size = UDim2.fromOffset(56, 24)     btn.Position = UDim2.fromOffset(54 + (i - 1) * 60, 30)     btn.BackgroundColor3 = Color3.fromRGB(60, 60, 90)     btn.Text = s     btn.TextSize = 12     btn.TextColor3 = Color3.new(1, 1, 1)     btn.Parent = panel     btn.MouseButton1Click:Connect(function()         CONFIG.shape = s         if CONFIG.active and lastTool then spawnClones(lastTool) end     end) end  -- 滑块组件 local function makeSlider(posY, label, minV, maxV, get, set)     local lab = Instance.new("TextLabel")     lab.Size = UDim2.fromOffset(46, 20)     lab.Position = UDim2.fromOffset(6, posY)     lab.BackgroundTransparency = 1     lab.Text = label     lab.TextColor3 = Color3.new(1, 1, 1)     lab.TextSize = 13     lab.Parent = panel      local bar = Instance.new("Frame")     bar.Size = UDim2.fromOffset(110, 6)     bar.Position = UDim2.fromOffset(58, posY + 7)     bar.BackgroundColor3 = Color3.fromRGB(80, 80, 110)     bar.Parent = panel      local fill = Instance.new("Frame")     fill.BackgroundColor3 = Color3.fromRGB(70, 210, 130)     fill.Parent = bar      local thumb = Instance.new("TextButton")     thumb.Size = UDim2.fromOffset(16, 16)     thumb.Text = ""     thumb.BackgroundColor3 = Color3.new(1, 1, 1)     thumb.Parent = bar      local val = Instance.new("TextLabel")     val.Size = UDim2.fromOffset(44, 20)     val.Position = UDim2.fromOffset(176, posY)     val.BackgroundTransparency = 1     val.TextColor3 = Color3.new(1, 1, 1)     val.TextSize = 13     val.Parent = panel      local function refresh(t)         t = math.clamp(t, 0, 1)         set(minV + (maxV - minV) * t)         fill.Size = UDim2.new(t, 0, 1, 0)         thumb.Position = UDim2.new(t, -8, 0, -5)         val.Text = string.format("%.1f", get())     end     refresh(0.5)      local dragging = false     thumb.InputBegan:Connect(function(inp)         if inp.UserInputType == Enum.UserInputType.MouseButton1 then dragging = true end     end)     thumb.InputEnded:Connect(function(inp)         if inp.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end     end)     thumb.MouseMoved:Connect(function(x)         if not dragging then return end         refresh((x - bar.AbsolutePosition.X) / bar.AbsoluteSize.X)     end)     return refresh end  local refreshSpeed = makeSlider(58, "速度", 0.5, 6, function() return CONFIG.speed end, function(v) CONFIG.speed = v end) local refreshScale = makeSlider(88, "大小", 0.5, 2.5, function() return CONFIG.scale end, function(v)     CONFIG.scale = v     if CONFIG.active and lastTool then spawnClones(lastTool) end end)  -- 开关逻辑 toggle.MouseButton1Click:Connect(function()     CONFIG.active = not CONFIG.active     if CONFIG.active then         toggle.BackgroundColor3 = Color3.fromRGB(220, 90, 70)         toggle.Text = "分身：开"         if lastTool then spawnClones(lastTool) end         panel.Visible = true     else         toggle.BackgroundColor3 = Color3.fromRGB(45, 160, 90)         toggle.Text = "分身：关"         clearClones()         panel.Visible = false     end end)
